create table if not exists public.local_income_entries(id uuid primary key default gen_random_uuid(),description text not null check(char_length(btrim(description)) between 2 and 160),category text not null,currency text not null check(currency in('USD','VES','COP')),amount numeric(14,2) not null check(amount>0),entry_date date not null default current_date,note text,created_by uuid references auth.users(id) on delete set null,created_at timestamptz not null default now(),check(currency<>'COP' or amount=trunc(amount)),check(category in('Otro ingreso','Reembolso','Comisión','Otro')));
create table if not exists public.cash_register_movements(id uuid primary key default gen_random_uuid(),movement_type text not null check(movement_type in('opening','in','out')),currency text not null check(currency in('USD','VES','COP')),amount numeric(14,2) not null check(amount>0),movement_date date not null default current_date,description text not null check(char_length(btrim(description)) between 2 and 160),created_by uuid references auth.users(id) on delete set null,created_at timestamptz not null default now(),check(currency<>'COP' or amount=trunc(amount)));
create index if not exists local_income_date_idx on public.local_income_entries(entry_date desc,created_at desc); create index if not exists cash_moves_date_idx on public.cash_register_movements(movement_date desc,created_at desc);
alter table public.local_income_entries enable row level security; alter table public.cash_register_movements enable row level security; revoke all on public.local_income_entries,public.cash_register_movements from public,anon,authenticated;
create or replace function public.admin_create_income(p_description text,p_category text,p_currency text,p_amount numeric,p_entry_date date,p_note text default null) returns uuid language plpgsql security definer set search_path='' as $$ declare x uuid; begin if auth.uid() is null or not public.is_chat_admin() then raise exception 'Sin permiso.' using errcode='42501'; end if; if p_description is null or char_length(btrim(p_description)) not between 2 and 160 or p_category not in('Otro ingreso','Reembolso','Comisión','Otro') or p_currency not in('USD','VES','COP') or p_amount<=0 or (p_currency='COP' and p_amount<>trunc(p_amount)) or p_entry_date is null or p_entry_date>current_date or (p_note is not null and char_length(p_note)>240) then raise exception 'Revisa los datos del ingreso.' using errcode='22023'; end if; insert into public.local_income_entries(description,category,currency,amount,entry_date,note,created_by) values(btrim(p_description),p_category,p_currency,case when p_currency='COP' then p_amount else round(p_amount,2) end,p_entry_date,nullif(btrim(p_note),''),auth.uid()) returning id into x; return x; end $$;
create or replace function public.admin_list_income(p_limit integer default 100) returns table(description text,category text,currency text,amount numeric,entry_date date,note text) language plpgsql stable security definer set search_path='' as $$ begin if auth.uid() is null or not public.is_chat_admin() then raise exception 'Sin permiso.' using errcode='42501'; end if; return query select e.description,e.category,e.currency,e.amount,e.entry_date,e.note from public.local_income_entries e order by e.entry_date desc,e.created_at desc limit greatest(1,least(coalesce(p_limit,100),500)); end $$;
create or replace function public.admin_create_cash_movement(p_movement_type text,p_currency text,p_amount numeric,p_movement_date date,p_description text) returns uuid language plpgsql security definer set search_path='' as $$ declare x uuid; begin if auth.uid() is null or not public.is_chat_admin() then raise exception 'Sin permiso.' using errcode='42501'; end if; if p_movement_type not in('opening','in','out') or p_currency not in('USD','VES','COP') or p_amount<=0 or (p_currency='COP' and p_amount<>trunc(p_amount)) or p_movement_date is null or p_movement_date>current_date or p_description is null or char_length(btrim(p_description)) not between 2 and 160 then raise exception 'Revisa los datos del movimiento.' using errcode='22023'; end if; insert into public.cash_register_movements(movement_type,currency,amount,movement_date,description,created_by) values(p_movement_type,p_currency,case when p_currency='COP' then p_amount else round(p_amount,2) end,p_movement_date,btrim(p_description),auth.uid()) returning id into x; return x; end $$;
create or replace function public.admin_list_cash_movements(p_limit integer default 100) returns table(description text,movement_type text,currency text,amount numeric,movement_date date) language plpgsql stable security definer set search_path='' as $$ begin if auth.uid() is null or not public.is_chat_admin() then raise exception 'Sin permiso.' using errcode='42501'; end if; return query select m.description,m.movement_type,m.currency,m.amount,m.movement_date from public.cash_register_movements m order by m.movement_date desc,m.created_at desc limit greatest(1,least(coalesce(p_limit,100),500)); end $$;
revoke all on function public.admin_create_income(text,text,text,numeric,date,text),public.admin_list_income(integer),public.admin_create_cash_movement(text,text,numeric,date,text),public.admin_list_cash_movements(integer) from public,anon; grant execute on function public.admin_create_income(text,text,text,numeric,date,text),public.admin_list_income(integer),public.admin_create_cash_movement(text,text,numeric,date,text),public.admin_list_cash_movements(integer) to authenticated; notify pgrst,'reload schema';
